import{_ as a,o as d,c as l,a2 as e}from"./chunks/framework.BUS5y9ZA.js";const _=JSON.parse('{"title":"올바름 인력관리시스템 디자인 가이드","description":"","frontmatter":{},"headers":[],"relativePath":"design-guide.md","filePath":"design-guide.md"}'),r={name:"design-guide.md"};function i(h,t,o,n,s,u){return d(),l("div",null,[...t[0]||(t[0]=[e('<h1 id="올바름-인력관리시스템-디자인-가이드" tabindex="-1">올바름 인력관리시스템 디자인 가이드 <a class="header-anchor" href="#올바름-인력관리시스템-디자인-가이드" aria-label="Permalink to &quot;올바름 인력관리시스템 디자인 가이드&quot;">​</a></h1><table tabindex="0"><thead><tr><th>항목</th><th>내용</th></tr></thead><tbody><tr><td>문서 유형</td><td>디자인 가이드</td></tr><tr><td>대상</td><td>회사소개 홈페이지, 관리자 웹, 현장 근무자 모바일 웹</td></tr><tr><td>기준 문서</td><td>요구사항분석서, 기능명세서, 화면명세서</td></tr></tbody></table><h2 id="_1-디자인-원칙" tabindex="-1">1. 디자인 원칙 <a class="header-anchor" href="#_1-디자인-원칙" aria-label="Permalink to &quot;1. 디자인 원칙&quot;">​</a></h2><ul><li>업무 정보를 빠르게 찾을 수 있도록 명확하고 일관된 화면을 제공한다.</li><li>관리자 화면은 목록·검색·입력 중심으로, 현장 근무자 화면은 한 손 조작이 쉬운 모바일 중심으로 설계한다.</li><li>장식보다 정보 위계, 충분한 여백, 읽기 쉬운 대비를 우선한다.</li><li>색상만으로 상태를 구분하지 않고 상태명과 안내 문구를 함께 제공한다.</li><li>PC와 모바일에서 동일한 업무 의미와 용어를 유지한다.</li></ul><h2 id="_2-색상" tabindex="-1">2. 색상 <a class="header-anchor" href="#_2-색상" aria-label="Permalink to &quot;2. 색상&quot;">​</a></h2><table tabindex="0"><thead><tr><th>용도</th><th>기준</th></tr></thead><tbody><tr><td>Primary</td><td>주요 버튼, 활성 메뉴, 핵심 강조에 사용</td></tr><tr><td>Canvas</td><td>페이지 기본 배경</td></tr><tr><td>Surface</td><td>카드, 입력 영역, 표 배경</td></tr><tr><td>Ink</td><td>제목과 본문 기본 글자</td></tr><tr><td>Muted</td><td>설명, 보조 정보, 비활성 정보</td></tr><tr><td>Hairline</td><td>표와 입력창의 경계선</td></tr><tr><td>Success/Warning/Error</td><td>처리 결과와 주의·오류 상태</td></tr></tbody></table><ul><li>실제 색상값은 <code>src/app/globals.css</code>의 디자인 토큰을 우선 적용한다.</li><li>컴포넌트에 임의 색상을 추가하기보다 공통 토큰을 확장한다.</li></ul><h2 id="_3-타이포그래피" tabindex="-1">3. 타이포그래피 <a class="header-anchor" href="#_3-타이포그래피" aria-label="Permalink to &quot;3. 타이포그래피&quot;">​</a></h2><ul><li>기본 글꼴은 Pretendard 계열을 사용한다.</li><li>페이지 제목은 32~40px, 섹션 제목은 20~24px, 본문은 15~17px를 권장한다.</li><li>입력 라벨과 표 머리글은 본문보다 작게 사용하되 12px 미만으로 축소하지 않는다.</li><li>제목, 버튼, 입력 라벨은 동일 화면에서 동일한 굵기 체계를 유지한다.</li></ul><h2 id="_4-레이아웃" tabindex="-1">4. 레이아웃 <a class="header-anchor" href="#_4-레이아웃" aria-label="Permalink to &quot;4. 레이아웃&quot;">​</a></h2><h3 id="_4-1-관리자-화면" tabindex="-1">4.1 관리자 화면 <a class="header-anchor" href="#_4-1-관리자-화면" aria-label="Permalink to &quot;4.1 관리자 화면&quot;">​</a></h3><ul><li>PC에서는 좌측 사이드바와 본문 영역을 사용하고, 모바일에서는 햄버거 메뉴로 전환한다.</li><li>본문 최대 폭은 업무 화면 특성에 따라 980~1180px를 기준으로 한다.</li><li>목록 화면은 제목, 조회 조건, 주요 작업, 결과 목록 순으로 구성한다.</li></ul><h3 id="_4-2-현장-근무자-화면" tabindex="-1">4.2 현장 근무자 화면 <a class="header-anchor" href="#_4-2-현장-근무자-화면" aria-label="Permalink to &quot;4.2 현장 근무자 화면&quot;">​</a></h3><ul><li>세로형 모바일 화면을 우선하며 주요 버튼은 충분한 터치 영역과 전체 폭을 확보한다.</li><li>위치·카메라·알림 등 권한이 필요한 기능은 요청 목적과 거부 시 대안을 안내한다.</li><li>처리 중에는 로딩 상태를 표시하고 중복 입력을 방지한다.</li></ul><h3 id="_4-3-회사소개-홈페이지" tabindex="-1">4.3 회사소개 홈페이지 <a class="header-anchor" href="#_4-3-회사소개-홈페이지" aria-label="Permalink to &quot;4.3 회사소개 홈페이지&quot;">​</a></h3><ul><li>대표 이미지와 핵심 메시지, 서비스 강점, 사회적 가치, 상담 신청, 회사 정보 순으로 구성한다.</li><li>카드 영역은 모바일 1열, 넓은 화면 3열을 기본으로 한다.</li></ul><h2 id="_5-공통-컴포넌트" tabindex="-1">5. 공통 컴포넌트 <a class="header-anchor" href="#_5-공통-컴포넌트" aria-label="Permalink to &quot;5. 공통 컴포넌트&quot;">​</a></h2><table tabindex="0"><thead><tr><th>컴포넌트</th><th>적용 기준</th></tr></thead><tbody><tr><td>기본 버튼</td><td>저장·등록·실행 등 주요 동작에 사용</td></tr><tr><td>보조 버튼</td><td>취소·뒤로가기·보조 동작에 사용</td></tr><tr><td>위험 버튼</td><td>삭제 등 복구가 어려운 동작에 사용하고 확인 절차 제공</td></tr><tr><td>입력창</td><td>라벨, 필수 여부, 오류 문구를 함께 제공</td></tr><tr><td>표</td><td>머리글 고정 의미, 행 구분, 모바일 대응 제공</td></tr><tr><td>모달</td><td>확인·상담·상세 안내처럼 현재 흐름을 유지해야 할 때 사용</td></tr><tr><td>상태 메시지</td><td>성공·경고·오류 결과를 문장으로 제공</td></tr></tbody></table><h2 id="_6-접근성-및-반응형" tabindex="-1">6. 접근성 및 반응형 <a class="header-anchor" href="#_6-접근성-및-반응형" aria-label="Permalink to &quot;6. 접근성 및 반응형&quot;">​</a></h2><ul><li>모든 입력 요소에 연결된 라벨을 제공한다.</li><li>키보드 포커스를 시각적으로 표시하고 버튼과 링크를 키보드로 실행할 수 있게 한다.</li><li>텍스트와 배경은 WCAG AA 수준의 대비를 목표로 한다.</li><li>모바일에서 가로 스크롤이 필요한 표는 카드형 전환 또는 안전한 스크롤 영역을 제공한다.</li><li>이미지에는 용도를 설명하는 대체 텍스트를 제공한다.</li></ul><h2 id="_7-변경-관리" tabindex="-1">7. 변경 관리 <a class="header-anchor" href="#_7-변경-관리" aria-label="Permalink to &quot;7. 변경 관리&quot;">​</a></h2><ul><li>공통 토큰이나 컴포넌트 변경 시 관리자·근무자·회사소개 화면의 영향을 함께 확인한다.</li><li>신규 화면은 <code>화면명세서.md</code>에 화면 ID와 동작을 먼저 반영한다.</li><li>구현 검수 시 PC, 모바일, 키보드 조작, 권한 거부 상태를 포함한다.</li></ul>',22)])])}const b=a(r,[["render",i]]);export{_ as __pageData,b as default};
